validator:
function validate(input) {
  const [{ Tasks = [], Executed = [] }] = input;
  const counts = new Map();
  for (const [id, count] of Tasks) {
    if (id === null) return 'Every task needs a task_id.';
    if (counts.has(id)) return `task_id ${id} appears twice in Tasks.`;
    if (!Number.isInteger(count) || count < 2 || count > 20) return `Task ${id} needs a subtasks_count from 2 to 20.`;
    counts.set(id, count);
  }
  const seen = new Set();
  for (const [id, sub] of Executed) {
    if (!counts.has(id)) return `Executed names task ${id}, which is not in Tasks.`;
    if (!Number.isInteger(sub) || sub < 1 || sub > counts.get(id)) return `Subtask ${sub} is out of range for task ${id}.`;
    const key = `${id}:${sub}`;
    if (seen.has(key)) return `Subtask ${sub} of task ${id} is listed twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const taskCount = small ? Math.floor(rand() * 5) : 300;
  const ids = Array.from({ length: small ? 8 : 1000 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Tasks = [], Executed = [];
  for (const id of ids.slice(0, taskCount)) {
    // Small cases keep counts low but sometimes hit the limit of 20.
    const count = small ? (rand() < 0.1 ? 20 : 2 + Math.floor(rand() * 4)) : 2 + Math.floor(rand() * 19);
    Tasks.push([id, count]);
    // Each task ran completely, not at all, or partly.
    const mode = rand();
    for (let sub = 1; sub <= count; sub++) {
      const ran = mode < 0.25 ? true : mode < 0.45 ? false : rand() < 0.5;
      if (ran && Executed.length < 2000) Executed.push([id, sub]);
    }
  }
  for (let i = Executed.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Executed[i], Executed[j]] = [Executed[j], Executed[i]]; }
  return [{ Tasks, Executed }];
}
